package cn.mop.persistence;
import cn.mop.domain.DomainException;
import cn.mop.domain.contact.*;
import cn.mop.domain.contact.CustomerContact.*;
import java.nio.charset.StandardCharsets;
import java.time.LocalTime;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ContactImportPayloadCodecTest {
    CustomerContact contact(String name){return new CustomerContact(name,Set.of(Role.REPORTER),null,null,null,null,null,false);}
    @Test void roundTripExactUnicodeAndUnknownFields(){var rows=List.of(contact("  SYNTHETIC_🙂  "));byte[] bytes=ContactImportPayloadCodec.encode(rows);assertEquals(rows,ContactImportPayloadCodec.decode(bytes,1,ContactImportPayloadCodec.hash(bytes)));}
    @Test void sameSetOrderGivesSameCanonicalBytesButRowOrderMatters(){var a=new CustomerContact("SYNTHETIC",new LinkedHashSet<>(List.of(Role.REPORTER,Role.DECISION_MAKER)),null,null,null,new LinkedHashSet<>(List.of(Priority.P2,Priority.P1)),null,true);var b=new CustomerContact("SYNTHETIC",new LinkedHashSet<>(List.of(Role.DECISION_MAKER,Role.REPORTER)),null,null,null,new LinkedHashSet<>(List.of(Priority.P1,Priority.P2)),null,true);assertArrayEquals(ContactImportPayloadCodec.encode(List.of(a)),ContactImportPayloadCodec.encode(List.of(b)));assertFalse(Arrays.equals(ContactImportPayloadCodec.encode(List.of(a,contact("other"))),ContactImportPayloadCodec.encode(List.of(contact("other"),a))));}
    @Test void unknownEmptyAndDeclaredQuietGroupsHaveDifferentHashes(){Set<String> hashes=new HashSet<>();for(var contact:List.of(contact("SYNTHETIC"),new CustomerContact("SYNTHETIC",Set.of(Role.REPORTER),null,null,null,Set.of(),null,false),new CustomerContact("SYNTHETIC",Set.of(Role.REPORTER),null,null,null,null,new QuietWindow(null,null,null),false),new CustomerContact("SYNTHETIC",Set.of(Role.REPORTER),null,null,null,null,new QuietWindow(false,null,null),false),new CustomerContact("SYNTHETIC",Set.of(Role.REPORTER),null,null,null,null,new QuietWindow(true,LocalTime.of(22,0),LocalTime.of(7,0)),false))){byte[] bytes=ContactImportPayloadCodec.encode(List.of(contact));assertEquals(contact,ContactImportPayloadCodec.decode(bytes,1,ContactImportPayloadCodec.hash(bytes)).get(0));assertTrue(hashes.add(ContactImportPayloadCodec.hash(bytes)));}}
    @Test void listBoundsAndNullRowsFailBeforeEncoding(){for(List<CustomerContact> rows:Arrays.asList(null,List.<CustomerContact>of(),Arrays.asList(contact("SYNTHETIC"),null),Collections.nCopies(101,contact("SYNTHETIC"))))assertThrows(DomainException.class,()->ContactImportPayloadCodec.encode(rows));byte[] bytes=ContactImportPayloadCodec.encode(Collections.nCopies(100,contact("SYNTHETIC")));assertEquals(100,ContactImportPayloadCodec.decode(bytes,100,ContactImportPayloadCodec.hash(bytes)).size());}
    @Test void byteCorruptionWrongDigestOrCountRejected(){byte[] bytes=ContactImportPayloadCodec.encode(List.of(contact("SYNTHETIC")));assertThrows(DomainException.class,()->ContactImportPayloadCodec.decode(bytes,1,"0".repeat(64)));assertThrows(DomainException.class,()->ContactImportPayloadCodec.decode(bytes,2,ContactImportPayloadCodec.hash(bytes)));byte[] broken=bytes.clone();broken[0]='[';assertThrows(DomainException.class,()->ContactImportPayloadCodec.decode(broken,1,ContactImportPayloadCodec.hash(broken)));}
    @Test void canonicalBytesRejectWhitespaceUnknownFieldsAndDuplicateKeys(){byte[] valid=ContactImportPayloadCodec.encode(List.of(contact("SYNTHETIC")));String original=new String(valid,StandardCharsets.UTF_8);for(String text:List.of(" "+original,original+" {}",original.replace("\"name\":\"SYNTHETIC\"","\"name\":\"x\",\"name\":\"SYNTHETIC\""),original.replace("\"enabled\":false","\"enabled\":false,\"tenant_id\":null"))){byte[] bytes=text.getBytes(StandardCharsets.UTF_8);assertThrows(DomainException.class,()->ContactImportPayloadCodec.decode(bytes,1,ContactImportPayloadCodec.hash(bytes)));}}
    @Test void badRowsNotDroppedOrDefaulted(){String source=new String(ContactImportPayloadCodec.encode(List.of(contact("SYNTHETIC"))),StandardCharsets.UTF_8);for(String text:List.of(source.replace("\"enabled\":false","\"enabled\":null"),source.replace("[\"REPORTER\"]","[\"REPORTER\",\"REPORTER\"]"),source.replace("\"mobile\":null","\"mobile\":\"13800000000\""))){byte[] bytes=text.getBytes(StandardCharsets.UTF_8);assertThrows(DomainException.class,()->ContactImportPayloadCodec.decode(bytes,1,ContactImportPayloadCodec.hash(bytes)));}}
    @Test void decodedCollectionsAndContactsAreImmutable(){byte[] bytes=ContactImportPayloadCodec.encode(List.of(contact("SYNTHETIC")));var rows=ContactImportPayloadCodec.decode(bytes,1,ContactImportPayloadCodec.hash(bytes));assertThrows(UnsupportedOperationException.class,rows::clear);assertThrows(UnsupportedOperationException.class,()->rows.get(0).roles().clear());}
}
